/* eslint-disable */
import SnackBar from "@/components/SnackBar.vue";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { team_api_key_generation } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  mixins: [get_Org_details],
  components: {
    SnackBar
  },
  data() {
    return {
      tableLoading: false,
      tableData: [],
      teamAPiKey: "",
      SnackBarComponent: {},
      loading: false,
      checkbox: false
    };
  },
  async created() {
    await this.get_Org_details();
    this.teamAPiKey = this.orgDetails.organization.team_api_key;
  },
  methods: {
    copyToClipboard_api_key() {
      const spanElement = this.$refs.textInputapi;
      const text = spanElement.innerText;
      if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(() => {
          // console.log("Text copied to clipboard");
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "APi Key copied to clipboard",
            timeout: 5000,
            Top: true
          };
        }).catch(err => {
          console.error("Failed to copy text: ", err);
        });
      } else {
        console.error("Clipboard API not supported in this browser.");
      }
    },
    async generate_apiKey() {
      if (this.checkbox == false) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please agree to proceed",
          timeout: 5000,
          Top: true
        };
      } else {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(team_api_key_generation, {
            input: {
              organization_id: data.organization.organization_id
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.team_api_key_generation);
          if (response.Status == "SUCCESS") {
            this.teamAPiKey = response.key;
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.checkbox = false;
          } else {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.checkbox = false;
          }
        } catch (error) {
          this.loading = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: error.errors[0].message,
            timeout: 5000,
            Top: true
          };
        }
      }
    }
  }
};
